<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch} from 'vue';
import {useSession} from './store';
import {workflowNodes} from '../../../packages/workflow/nodes';
const props=defineProps<{language:'zh'|'en'}>(),emit=defineEmits<{navigate:[stage:'references'|'model'|'mapping'|'cutting'|'pattern',id?:string,tab?:'materials'|'seams'|'nesting']}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const project=computed(()=>store.data.project),selected=ref('references'),title=ref(''),notes=ref(''),completed=ref(false);
const nodes=computed(()=>project.value?workflowNodes(project.value,zh.value):[]);
const node=computed(()=>nodes.value.find(n=>n.key===selected.value));
watch(node,n=>{title.value=n?.title??'';notes.value=n&&'notes' in n?n.notes??'':'';completed.value=n&&'completed' in n?!!n.completed:false;},{immediate:true});
watch(()=>project.value?.id,()=>{selected.value='references';});
async function save(){const p=project.value,n=node.value;if(p&&n)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'workflow.node',node:{key:n.key,title:title.value.trim(),notes:notes.value,completed:completed.value}}));}
async function exchange(action:'import'|'export'){const p=project.value;if(p)await store.run(()=>window.fpcad.workflowFile(p.id,p.revision,action));}
async function editNode(){const n=node.value,p=project.value;if(!n||!p)return;if(n.key.startsWith('model:')){const id=n.key.slice(6);if(p.surface?.id!==id&&!await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'model.activate',modelId:id})))return;}
 emit('navigate',n.stage,'id' in n&&typeof n.id==='string'?n.id:undefined,'tab' in n?n.tab as 'materials'|'seams'|'nesting':undefined);}
</script>
<template><section class="workflow-page" aria-label="制作流程"><div class="flow-header"><span class="eyebrow">PROJECT / {{zh?'制作流程':localize('PRODUCTION FLOW')}}</span><h2>{{project?.name}}</h2><p>{{zh?'当前项目的所有步骤和对象保存在同一制作流中。选择节点可修改记录，或进入对应页面编辑实际内容。':localize('Every process and project entity belongs to this production flow. Select a node to update its record or open its editor.')}}</p><button :disabled="store.busy" @click="exchange('export')">{{zh?'导出制作流 JSON':localize('Export workflow JSON')}}</button><button :disabled="store.busy" @click="exchange('import')">{{zh?'导入制作流 JSON':localize('Import workflow JSON')}}</button></div><div class="flow-content"><div class="flow-nodes"><button v-for="(n,i) in nodes" :key="n.key" :class="['flow-node',{active:selected===n.key,stage:i<5}]" @click="selected=n.key"><span>{{i<5?String(i+1).padStart(2,'0'):'↳'}}</span><div><strong>{{n.title}}</strong><small>{{n.summary}}</small></div><b>{{'completed' in n&&n.completed?'✓':'○'}}</b></button></div><section v-if="node" class="node-record"><h3>{{zh?'节点记录':localize('Node record')}}</h3><label>{{zh?'节点名称':localize('Node title')}}<input v-model="title" maxlength="120"></label><label>{{zh?'制作说明与调整记录':localize('Production notes')}}<textarea v-model="notes" rows="7" maxlength="4000"></textarea></label><label class="check-label"><input v-model="completed" type="checkbox">{{zh?'已完成此节点':localize('Node completed')}}</label><button :disabled="store.busy||!title.trim()" @click="save">{{zh?'保存节点':localize('Save node')}}</button><button class="primary" :disabled="store.busy" @click="editNode">{{zh?'编辑此节点内容 →':localize('Edit node content →')}}</button><small>{{zh?'节点记录和完成状态不替代几何与制造检查。导入会建立新的本地项目，保留当前项目。':localize('Notes and completion do not replace geometry checks. Import creates a new local project and retains the current one.')}}</small></section></div></section></template>
<style scoped>.workflow-page{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden;background:var(--panel-soft)}.flow-header{padding:25px 28px;border-bottom:1px solid var(--border)}h2{font-size:24px;margin:8px 0}p,small{color:var(--accent);font-size:12px;line-height:1.8}.flow-header button{margin-right:8px}.flow-content{display:grid;grid-template-columns:minmax(200px,1fr) minmax(230px,.8fr);min-height:0;flex:1}.flow-nodes{overflow:auto;padding:20px}.flow-node{display:flex;align-items:center;gap:12px;width:100%;text-align:left;margin-bottom:8px;background:var(--panel)}.flow-node>span{color:var(--accent);font-size:18px}.flow-node>div{flex:1;min-width:0}.flow-node strong,.flow-node small{display:block;overflow-wrap:anywhere}.flow-node.stage{padding:16px}.flow-node.active{border-color:var(--accent)}.node-record{padding:20px;border-left:1px solid var(--border);overflow:auto}.node-record label{display:block;margin:14px 0;font-size:12px}.node-record textarea{width:100%;background:var(--panel);color:var(--text-muted);border:1px solid var(--border);border-radius:4px;padding:8px;resize:vertical}.node-record button{display:block;width:100%;margin:10px 0}.node-record small{display:block}@media(max-width:1100px){.flow-content{grid-template-columns:1fr}.node-record{border-top:1px solid var(--border);max-height:280px}.flow-header{padding:18px}.flow-nodes{padding:12px}}</style>
